// Actual native command and approval; model and worker identities are synthetic.
void durable_process_host_contract(const std::vector<std::string>& imports,const std::string& executable){
    for(const std::string mode:{"approved","denied","policy","cancel","unrecorded","retired","background","background_unrecorded"}){
        std::cout<<"Durable process host case "<<mode<<std::endl;
        const bool background=mode.starts_with("background"),unrecorded=mode=="unrecorded"||mode=="background_unrecorded",approved=mode=="approved"||mode=="background";
        Directory directory;const auto primary=directory.path/"primary",extra=directory.path/"attached";std::filesystem::create_directory(primary);std::filesystem::create_directory(extra);
        WorkspaceTools workspace(primary.string()),attached(extra.string());WorkspaceToolSet members(workspace.identity(),7,{{workspace.identity(),workspace.root_path()},{attached.identity(),attached.root_path()}});
        RepositoryInstructionContext guidance(workspace,workspace.repository_instructions(".")),extra_guidance(attached,attached.repository_instructions("."));guidance.prepare();extra_guidance.prepare();
        const auto database=(directory.path/"durable.sqlite").string();const std::string provider=R"({"wire":"chat-completions","model_id":"worker-process-fixture"})";std::string operation;
        {
            PersistenceService store(database,imports);store.create_session("session","Durable process host").get();store.start_prompt_run("run","session",R"({"content":"Synthetic admission for actual approved command"})",RootBudgetSpec{"native.direct-agent",1,workspace.identity(),provider,0,0,8,600000}).get();store.transition("run",RunState::queued,RunState::running).get();
            store.append_event("run","agent.workspace_membership",Json{{"workspace_id",workspace.identity()},{"revision",7},{"primary_folder_id",workspace.identity()},{"folders",Json::array({{{"folder_id",workspace.identity()},{"root",workspace.root_path()}},{{"folder_id",attached.identity()},{"root",attached.root_path()}}})}}.dump()).get();
            const auto deadline=std::chrono::steady_clock::now()+20s;const auto lease=store.admit_agent_worker({"process-host-generation","run","run",workspace.identity(),7,12345,"134000000000000000","synthetic-process-host-identity",provider}).get().spec;
            AgentProcessToolInvocation call;call.run_id="run";call.attempt_id="process-model";call.call_id="actual-command";call.workspace_id=workspace.identity();call.folder_id=attached.identity();call.workspace_revision=7;call.tool_name="run_process";call.arguments_json=Json{{"profile","xlang3"},{"arguments",Json::array({"-B","-c","import sys; assert sys.implementation.name == 'xlang3'; from pathlib import Path; Path('durable-marker.txt').write_bytes(b'durable command\\n'); print('durable-process-ok')"})},{"folder_id",attached.identity()},{"workdir","."},{"timeout_ms",10000}}.dump();
            if(background){auto args=Json::parse(call.arguments_json);args["background"]=true;args["persistent"]=true;args["timeout_ms"]=30000;args["arguments"]=Json::array({"-B","-c","import time; from pathlib import Path; Path('durable-marker.txt').write_bytes(b'durable command\\n'); time.sleep(25)"});call.arguments_json=args.dump();}
            ModelCompletion response{"","","tool_calls",R"({"total_tokens":17})",{{call.call_id,call.tool_name,call.arguments_json}},"[]"};store.reserve_agent_worker_model(lease,call.attempt_id,deadline).get();store.start_agent_worker_model(lease,call.attempt_id,deadline).get();AgentWorkerModelClaimSpec model{lease.generation,"run","run",call.attempt_id,context_digest("synthetic captured process model input")};store.claim_agent_worker_model(model).get();store.record_agent_worker_model_response(model,encode_agent_model_completion(response),format_agent_model_assistant(response,"worker-process-fixture",23,5)).get();store.finish_agent_worker_model(lease,call.attempt_id,deadline).get();
            ProcessProfile profile{"xlang3",executable,1,{},35s};profile.xlang3_library=imports.at(1);ProcessExecutor executor(store,workspace,workspace.root_path(),{profile});AgentProcessToolOwnerContext owner;owner.run_id="run";owner.process=&executor;owner.primary_workspace=&workspace;owner.workspace_members=&members;owner.repository_context=[&](std::size_t i){return i==0?&guidance:i==1?&extra_guidance:nullptr;};owner.offered_tool=is_agent_process_tool;owner.deadline=deadline;owner.allow_background=background;if(mode=="policy")owner.permission_layers={{{"run_process","*","deny"}}};
            AgentWorkerProcessHost host(store,lease,owner,deadline);std::unique_ptr<XlangSqlite> fault;if(unrecorded){fault=std::make_unique<XlangSqlite>(database,imports);fault->execute("CREATE TRIGGER fixture_process_result_abort BEFORE UPDATE ON information WHEN OLD.category='native-agent-worker-process-claims' AND json_extract(NEW.payload,'$.state')='returned' BEGIN SELECT RAISE(ABORT,'fixture_process_result_abort'); END");}
            if(mode=="policy"){const auto result=host.invoke(call);need(!result.success&&Json::parse(result.output_json)["error"]["code"]=="agent_permission_denied"&&store.operations("run").get().empty(),"Inherited denial must precede any command proposal");}
            else {Task task(host,call);const auto proposal=pending(store,&task);operation=proposal.id;const auto waiting=store.agent_worker_process_claim("run",call.attempt_id,call.call_id).get();need(waiting.state=="executing"&&waiting.operation_ids.empty()&&!std::filesystem::exists(extra/"durable-marker.txt"),"Process invocation must be durable while actual approval is pending");
                if(mode=="cancel")task.stop.request_stop();else {if(mode=="retired")store.retire_agent_worker(lease.generation,"worker_exit").get();store.decide_operation(proposal.id,mode=="denied"?OperationDecision::deny:OperationDecision::allow,"fixture-controller").get();}
                if(mode=="cancel")rejects<ToolCancelled>([&]{task.result.get();});else if(unrecorded)rejects<ProcessOutcomeUnrecorded>([&]{task.result.get();});else if(mode=="retired")rejects<Conflict>([&]{task.result.get();});else {const auto result=task.result.get();need(result.success==approved,"Actual command result must reflect controller decision");if(result.success&&!background)need(Json::parse(result.output_json).at("exit_code")==0,"Durable command must retain actual zero exit");}
            }
            if(background){const auto until=std::chrono::steady_clock::now()+5s;while(!std::filesystem::exists(extra/"durable-marker.txt")&&std::chrono::steady_clock::now()<until)std::this_thread::sleep_for(5ms);const auto started=store.agent_worker_process_claim("run",call.attempt_id,call.call_id).get();need(started.operation_ids==std::vector<std::string>{operation}&&store.operation(operation).get().state==OperationState::executing,"Background result must retain its native dispatch binding before acknowledgement");const auto stopped=Json::parse(executor.stop("run",Json{{"job_id",operation}}.dump()));need(stopped.at("state")=="succeeded","Fixture cleanup must observe actual intentional service retirement");}
            if(fault)fault->execute("DROP TRIGGER fixture_process_result_abort");const auto saved=store.agent_worker_process_claim("run",call.attempt_id,call.call_id).get();const bool effect=approved||unrecorded;
            need(std::filesystem::exists(extra/"durable-marker.txt")==effect&&!std::filesystem::exists(primary/"durable-marker.txt"),"Only an approved command may mutate its admitted attached folder");if(effect)need(read(extra/"durable-marker.txt")=="durable command\n"&&saved.operation_ids==std::vector<std::string>{operation}&&store.operation(operation).get().state==OperationState::succeeded,"Actual native effect and operation must remain bound exactly once");
            if(unrecorded)need(saved.state=="executing"&&saved.actual_output_json.empty(),"Unrecorded command result must not fabricate an acknowledgement");else need(saved.state=="returned"&&saved.success==approved,"Known command outcomes must be recorded before delivery");
            AgentWorkerProcessHost rebuilt(store,lease,owner,deadline);rejects<Conflict>([&]{rebuilt.invoke(call);});if(mode!="retired")store.retire_agent_worker(lease.generation,"worker_exit").get();store.transition("run",RunState::running,RunState::cancelled).get();
        }
        {PersistenceService reopened(database,imports);const auto saved=reopened.agent_worker_process_claim("run","process-model","actual-command").get();need(saved.state==(unrecorded?"uncertain":"returned"),"SQLite reopen must retain acknowledged and uncertain command ownership");}
        std::cout<<"Durable native process host "<<mode<<" verified actual approval, command scope, durable receipt and reconstruction replay rejection. Synthetic model and worker identity; no process RPC."<<std::endl;
    }
}
